# queue 202: _sre's matcher iterative (an explicit backtracking stack, as sre_lib.h's): long repetitions (test_re's
# test_stack_overflow) no longer grow Go's stack, and the backtracking's semantics stay CPython's: branches, greedy,
# lazy and possessive repeats, atomic groups, lookarounds, backreferences, conditionals, marks restored on backtracking;
# then patterns generated by a fixed LCG, matched against strings over "ab" and compared by their spans and groups
import re

# test_re.test_stack_overflow: 50,000 repetitions of a group (REPEAT with MAX_UNTIL and MIN_UNTIL)
print(re.match('(x)*', 50000 * 'x').group(1), re.match('(x)*y', 50000 * 'x' + 'y').group(1),
      re.match('(x)*?y', 50000 * 'x' + 'y').group(1))
print(re.match('(?:ab)*c', 20000 * 'ab' + 'c').end(), re.match('(?:a|b)*?c', 20000 * 'ab' + 'c').end(),
      re.match('(?:ab)*+c', 20000 * 'ab' + 'c').end(), re.match('(?>(?:ab)*)c', 20000 * 'ab' + 'c').end())
print(re.match('(a|b)*$', 30000 * 'ab').span(), re.fullmatch('((a)|b)+', 30000 * 'ab').groups())
print(len(re.findall(r'(?:x+x+)+y', 'x' * 10)), re.search(r'(a+)+b', 'a' * 12) is None)

