    (r'(bc+d$|ef*g.|h?i(j|k))', 'reffgz'), (r'((a)|(b))*', 'ab'), (r'(?:(a)|b)*', 'ab'), (r'(a)*?b', 'aab'),
    (r'(a)+?b', 'aab'), (r'(a){2,3}?', 'aaaa'), (r'(a){2,3}', 'aaaa'), (r'(ab|a)*?b', 'ababab'),
    (r'(?=(a+))a*b\1', 'baaabac'), (r'(?=(a+?))(\1ab)', 'aaab'), (r'(?!(a)b)\w', 'abac'), (r'(?<=(a))b', 'ab'),
    (r'(?<!a)b', 'ab cb'), (r'(a)?(?(1)b|c)', 'ac'), (r'(a)?(?(1)b|c)', 'c'), (r'^(?:(a)|b)(?(1)x|y)$', 'by'),
    (r'(?>a*)a', 'aaa'), (r'(?>a*?)a', 'aaa'), (r'(a)*+a', 'aaa'), (r'(?:a|ab)++c', 'ababc'), (r'a*+b', 'aaab'),
