print(re.sub(r'(a|b)*?', '-', 'abc'), re.split(r'(?:a|b)*', 'xabyab'), re.findall(r'(a)|b', 'abab'),
      [m.span() for m in re.finditer(r'(?:a*?)', 'aab')], re.fullmatch(r'(a|ab)(c)', 'abc').groups())


class LCG:
    def __init__(self, seed):
        self.x = seed

    def next(self, n):
        self.x = (self.x * 1103515245 + 12345) % 2147483648
        return (self.x >> 16) % n


def gen(r, depth):
    k = r.next(12 if depth < 3 else 4)
    if k <= 1:
        return 'a'
    if k == 2:
        return 'b'
    if k == 3:
        return '.'
    if k == 4:
        return gen(r, depth + 1) + gen(r, depth + 1)
    if k == 5:
        return '(' + gen(r, depth + 1) + '|' + gen(r, depth + 1) + ')'
    if k == 6:
        return '(' + gen(r, depth + 1) + ')' + ['*', '+', '?', '*?', '+?', '??', '{1,2}', '{0,2}?', '*+', '++'][r.next(10)]
    if k == 7:
        return '(?:' + gen(r, depth + 1) + ')' + ['*', '+', '*?', '{2}', '{1,3}?', '?+'][r.next(6)]
    if k == 8:
        return gen(r, depth + 1) + ['*', '+', '?', '*?', '+?', '*+'][r.next(6)]
    if k == 9:
        return ['(?=', '(?!', '(?>'][r.next(3)] + gen(r, depth + 1) + ')'
    if k == 10:
        return ['(?<=a)', '(?<!b)', '^', '$', r'\b'][r.next(5)]
    return '(' + gen(r, depth + 1) + ')\\1' if r.next(2) else '[ab]'


r = LCG(202)
lines = 0
for i in range(150):
    p = gen(r, 0)
    try:
        rx = re.compile(p)
    except re.error as e:
        print(i, p, 'error', e)
        continue
    out = []
    for s in ('', 'a', 'ab', 'ba', 'aab', 'abab', 'bbaab', 'aaaa'):
        m = rx.search(s)
        out.append(m and (m.span(), m.groups()))
    out.append(rx.findall('abaabba'))
    print(i, p, out)
